// ==========================================
// ПОРТАЛЬНАЯ ПУШКА — ЗЕЛЁНЫЙ ПОРТАЛ
// ==========================================

const int greenPin = 9;     // зелёный канал RGB (пин 9)
const int buttonPin = 2;    // кнопка (пин 2)

bool isOn = false;          // состояние: включён/выключен

void setup() {
  pinMode(greenPin, OUTPUT);
  pinMode(buttonPin, INPUT_PULLUP);  // встроенный резистор подтяжки
  digitalWrite(greenPin, LOW);       // начинаем с выключенного
}

void loop() {
  // Если кнопка нажата (на пине 2 появляется LOW)
  if (digitalRead(buttonPin) == LOW) {
    delay(100);              // защита от дребезга (чтобы не срабатывало несколько раз)
    isOn = !isOn;            // переключаем состояние

    if (isOn) {
      digitalWrite(greenPin, HIGH);  // ЗЕЛЁНЫЙ ГОРИТ!
    } else {
      digitalWrite(greenPin, LOW);   // ЗЕЛЁНЫЙ ГАСНЕТ
    }
  }
}
